#!/usr/bin/env node
// Write the HTML for the 1200x630 social card, to stdout.
//
//   node src/build/social-card.mjs > /tmp/card.html
//   # then screenshot it at 1200x630 and save as ./social-card.png
//
// The PNG is COMMITTED rather than generated by build.sh, because turning a page
// into an image needs a browser and this project builds with Node and nothing
// else. This script is here so the card can be regenerated deliberately when the
// pitch changes, not so the build depends on it.
//
// The diagram in the card is the real how-it-works sheet, drawn by the real
// renderer and cropped to its first steps — not a mock-up, and not the whole
// sheet shrunk until the words stop resolving, which is the mistake the card is
// advertising the fix for.

import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { buildDocument } from "../layout.mjs";
import { renderDiagram } from "../svg.mjs";

const SRC = resolve(dirname(fileURLToPath(import.meta.url)), "..");

/** Contents of the first `{ … }` after `from`, brace-matched. */
function blockAfter(s, from) {
  const open = s.indexOf("{", from);
  let depth = 0;
  for (let i = open; i < s.length; i++) {
    if (s[i] === "{") depth++;
    else if (s[i] === "}") { depth--; if (!depth) return s.slice(open + 1, i); }
  }
  return "";
}

const css = readFileSync(resolve(SRC, "assets/theme.css"), "utf8");
const rootVars = blockAfter(css, css.indexOf(":root {")).trim();
const dBegin = css.indexOf("/* ----------------------------------------------------- diagram styles */");
const dEnd = css.indexOf("/* --------------------------------------------------------------- legend */");
if (dBegin < 0 || dEnd < 0) throw new Error("could not find the diagram style block in theme.css");
const diagramRules = css.slice(dBegin, dEnd).trim();

const doc = JSON.parse(readFileSync(resolve(SRC, "examples/how-it-works.wfd.json"), "utf8"));
const built = buildDocument(doc);
if (built.errors.length) {
  for (const e of built.errors) console.error(`error: ${e.path} — ${e.message}`);
  process.exit(1);
}
const { svg } = renderDiagram(built.workflows[0]);

// The spine's first boxes, at a scale where the titles are readable.
const CX = 14, CY = 14, CW = 312, CH = 566;
const PANEL_W = 452;
const scale = PANEL_W / CW;

process.stdout.write(`<!doctype html><html><head><meta charset="utf-8"><style>
:root{${rootVars}}
${diagramRules}
*{box-sizing:border-box;margin:0;padding:0;}
html,body{width:1200px;height:630px;overflow:hidden;}
.card{position:relative;width:1200px;height:630px;background:var(--paper);
  background-image:radial-gradient(ellipse 900px 520px at 6% -12%, color-mix(in oklab, var(--accent) 16%, transparent), transparent 70%);}
.left{position:absolute;left:72px;top:0;width:600px;height:630px;
  display:flex;flex-direction:column;justify-content:center;}
.eyebrow{font-family:var(--sans);font-size:14px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--accent);font-weight:700;margin-bottom:20px;}
h1{font-family:var(--serif);font-weight:500;letter-spacing:-.022em;font-size:50px;line-height:1.06;
  color:var(--ink);margin-bottom:20px;}
.sub{font-family:var(--sans);font-size:19px;line-height:1.5;color:var(--ink-2);
  margin-bottom:28px;max-width:32ch;}
.chips{display:flex;gap:8px;}
.chips span{font-family:var(--sans);font-size:13.5px;color:var(--ink-2);background:var(--surface);
  border:1px solid var(--line);border-radius:999px;padding:6px 14px;font-weight:600;white-space:nowrap;}
.right{position:absolute;right:44px;top:46px;width:${PANEL_W + 40}px;height:538px;
  background:var(--surface);border:1px solid var(--line);border-radius:16px;
  box-shadow:0 30px 70px -26px rgba(23,26,24,.36);overflow:hidden;padding:20px;transform:rotate(-1.5deg);}
.right svg{display:block;}
.fade{position:absolute;left:0;right:0;bottom:0;height:96px;
  background:linear-gradient(to bottom, transparent, var(--surface) 82%);}
</style></head><body><div class="card">
  <div class="left">
    <div class="eyebrow">workflowForge</div>
    <h1>Paste a workflow.<br>Get a page you can send.</h1>
    <div class="sub">A rendering engine for workflow diagrams &mdash; it draws yours without ever reading it.</div>
    <div class="chips"><span>One HTML file</span><span>No account</span><span>No network</span></div>
  </div>
  <div class="right">
    <svg viewBox="${CX} ${CY} ${CW} ${CH}" width="${PANEL_W}" height="${Math.round(CH * scale)}">${svg}</svg>
    <div class="fade"></div>
  </div>
</div></body></html>`);
